// Read the incoming WhatsApp message
const trig = $('WhatsApp Trigger').first().json;
const msg = (trig.messages || [])[0];
if (!msg) return [];            // delivery/read status updates -> ignore

const store = $getWorkflowStaticData('global');
store.leads = store.leads || {};
store.conversations = store.conversations || {};
store.seen = store.seen || [];

// Ignore duplicate webhook deliveries
if (store.seen.includes(msg.id)) return [];
store.seen.push(msg.id);
store.seen = store.seen.slice(-100);

const phone = String(msg.from);
const profileName = (((trig.contacts || [])[0] || {}).profile || {}).name || '';
const phoneNumberId = (trig.metadata || {}).phone_number_id;

let text = '';
if (msg.type === 'text') text = (msg.text || {}).body || '';
else if (msg.type === 'button') text = (msg.button || {}).text || '';
else if (msg.type === 'interactive') {
  const i = msg.interactive || {};
  text = (i.button_reply || i.list_reply || {}).title || '';
}
else if (msg.type === 'image') text = '[Customer sent an image] ' + ((msg.image || {}).caption || '');
else if (msg.type === 'audio') text = '[Customer sent a voice note which you cannot listen to. Politely ask them to type their message.]';
else text = '[Customer sent a ' + msg.type + ' message which you cannot read. Politely ask them to type.]';

// Lead profile + pause state
const lead = store.leads[phone] ? { ...store.leads[phone] } : {};
if (!lead.name && profileName) lead.name = profileName;

let paused = !!lead.ai_paused;
if (paused && lead.paused_at && (Date.now() - new Date(lead.paused_at).getTime()) > 12 * 3600 * 1000) {
  paused = false;                 // auto-resume the AI after 12 hours
  lead.ai_paused = false;
  lead.human_requested = false;
}
store.leads[phone] = lead;

// Inventory (only Available rows)
const inventory = $input.all()
  .map(i => i.json)
  .filter(p => p && p.PropertyID && String(p.Status || '').trim().toLowerCase() === 'available')
  .slice(0, 60);

const inv = inventory.map(p => ({
  id: String(p.PropertyID),
  title: p.Title,
  location: p.Location,
  purpose: p.Purpose,
  type: p.Type,
  price: (p.Currency || 'AED') + ' ' + p.Price,
  bedrooms: p.Bedrooms,
  bathrooms: p.Bathrooms,
  size: p.Size,
  description: String(p.Description || '').slice(0, 160)
}));

const history = (store.conversations[phone] || []).slice(-12);

const prompt =
  'KNOWN LEAD PROFILE:\n' + JSON.stringify(lead) +
  '\n\nRECENT CONVERSATION:\n' + JSON.stringify(history) +
  '\n\nAVAILABLE INVENTORY (the ONLY properties you may recommend):\n' + JSON.stringify(inv) +
  '\n\nLATEST CUSTOMER MESSAGE:\n' + text;

return [{ json: { phone, phone_number_id: phoneNumberId, user_text: text, lead, history, inventory, prompt, ai_paused: paused } }];

const ctx = $('Prepare Conversation').first().json;
const first = $input.first().json;

// ---- 1. Read the AI answer (works for object or text) ----
let raw = first.output;
if (raw === undefined) raw = first.text !== undefined ? first.text : '';
let ai = {};
if (raw && typeof raw === 'object') {
  ai = raw;
} else {
  const s = String(raw);
  const m = s.match(/\{[\s\S]*\}/);
  try {
    ai = JSON.parse(m ? m[0] : s);
  } catch (e) {
    ai = { reply: s.includes('{') ? 'Thank you for your message! Could you tell me a little more about what you are looking for?' : s.replace(/```json|```/g, '').trim() };
  }
}

const phone = ctx.phone;
const now = new Date().toISOString();
const store = $getWorkflowStaticData('global');
store.leads = store.leads || {};
store.conversations = store.conversations || {};

// ---- 2. Merge lead profile ----
const old = store.leads[phone] || ctx.lead || {};
const lead = { ...old };
const updates = (ai.lead_updates && typeof ai.lead_updates === 'object') ? ai.lead_updates : {};
for (const [k, v] of Object.entries(updates)) {
  if (v === null || v === undefined || v === '') continue;
  lead[k] = (typeof v === 'object') ? JSON.stringify(v) : v;
}

const delta = Math.max(0, Math.min(30, parseInt(ai.score_delta) || 0));
lead.phone = phone;
lead.score = Math.min(100, (parseInt(old.score) || 0) + delta);
lead.temperature = ['cold', 'warm', 'hot'].includes(ai.temperature) ? ai.temperature : (old.temperature || 'cold');
lead.language = ai.language || old.language || '';
lead.summary = ai.summary || old.summary || '';

const humanNow = (ai.human_requested === true || ai.human_requested === 'true');
lead.human_requested = humanNow || !!old.human_requested;
if (humanNow && !old.ai_paused) lead.paused_at = now;
lead.ai_paused = lead.human_requested;
lead.updated_at = now;
if (!lead.created_at) lead.created_at = now;

// ---- 3. Build WhatsApp messages (text first, then property cards) ----
const reply = (ai.reply && String(ai.reply).trim()) || 'Thank you for your message! One moment please.';
const url = 'https://graph.facebook.com/v23.0/' + ctx.phone_number_id + '/messages';
const messages = [{
  url,
  body: { messaging_product: 'whatsapp', to: phone, type: 'text', text: { body: reply.slice(0, 4000) } }
}];

const fmt = (v) => { const n = Number(String(v).replace(/,/g, '')); return isNaN(n) ? String(v) : n.toLocaleString('en-US'); };
const ids = Array.isArray(ai.property_ids) ? ai.property_ids.map(String).slice(0, 3) : [];
const shown = [];
for (const id of ids) {
  const p = (ctx.inventory || []).find(x => String(x.PropertyID) === id);
  if (!p) continue;
  shown.push(id);
  const caption = [
    '🏠 ' + (p.Title || ''),
    '📍 ' + (p.Location || ''),
    '💰 ' + (p.Currency || 'AED') + ' ' + fmt(p.Price),
    '🛏 ' + (p.Bedrooms || '-') + ' Bed | 🚿 ' + (p.Bathrooms || '-') + ' Bath' + (p.Size ? ' | 📐 ' + p.Size : ''),
    p.Description ? '\n' + String(p.Description).slice(0, 400) : ''
  ].join('\n').slice(0, 1000);
  const img = String(p.ImageURL || '').trim();
  if (img.startsWith('http')) {
    messages.push({ url, body: { messaging_product: 'whatsapp', to: phone, type: 'image', image: { link: img, caption } } });
  } else {
    messages.push({ url, body: { messaging_product: 'whatsapp', to: phone, type: 'text', text: { body: caption } } });
  }
}
if (shown.length) lead.properties_shown = [...new Set([...(String(lead.properties_shown || '').split(',').filter(Boolean)), ...shown])].join(',');

// ---- 4. Save to memory ----
store.leads[phone] = lead;
const hist = Array.isArray(store.conversations[phone]) ? store.conversations[phone] : [];
hist.push({ role: 'customer', text: ctx.user_text, ts: now });
hist.push({ role: 'assistant', text: reply, ts: now });
store.conversations[phone] = hist.slice(-20);

// ---- 5. Row for the CRM sheet ----
const g = (k) => (lead[k] === undefined || lead[k] === null) ? '' : lead[k];
const crm = {
  phone, name: g('name'), temperature: g('temperature'), score: g('score'),
  intent: g('intent'), purpose: g('purpose'), property_type: g('property_type'),
  bedrooms: g('bedrooms'), bathrooms: g('bathrooms'), budget: g('budget'), currency: g('currency'),
  area: g('area'), ready_or_offplan: g('ready_or_offplan'), payment_method: g('payment_method'),
  timeline: g('timeline'), viewing_time: g('viewing_time'), language: g('language'),
  summary: g('summary'), properties_shown: g('properties_shown'),
  human_requested: lead.human_requested ? 'YES' : 'no',
  last_message: ctx.user_text, updated_at: now
};

return [{ json: { phone, human_requested: lead.human_requested, messages, crm } }];

